mapper.select:
SELECT EXISTS (
  SELECT 1 FROM team_member
  WHERE team_id = #{teamId}
    AND user_id = #{userId}
    AND status = 'ACTIVE'
)

SELECT team_role
FROM team_member
WHERE team_id = #{teamId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'
LIMIT 1

mapper.delete:
DELETE FROM matching_bookmark
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}

mapper.select:
SELECT COUNT(*)
FROM team_invitation
WHERE team_id = #{teamId}
  AND slot_id = #{slotId}
  AND target_user_id = #{targetUserId}
  AND status = 'PENDING'

SELECT COUNT(*)
FROM team_application
WHERE team_id = #{teamId}
  AND slot_id = #{slotId}
  AND applicant_user_id = #{applicantUserId}
  AND status = 'PENDING'
